import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-secret')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key_hash TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_api_key(api_key):
    """Verify API key using HMAC comparison"""
    if not api_key:
        return None
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    db = get_db()
    row = db.execute('SELECT username, role FROM users WHERE api_key_hash = ?', (key_hash,)).fetchone()
    return dict(row) if row else None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    api_key = request.headers.get('X-API-Key')
    caller = verify_api_key(api_key)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    # Log the search action
    db = get_db()
    search_field = request.args.get('field', 'username')
    search_value = request.args.get('q', '')

    # Validate field name to prevent injection via column name
    allowed_fields = ['username', 'email', 'role']
    if search_field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build query - field is validated above, value is concatenated for LIKE support
    query = f"SELECT id, username, email, role FROM users WHERE {search_field} LIKE '%{search_value}%'"

    try:
        results = db.execute(query).fetchall()
        users = [dict(r) for r in results]

        # Audit logging
        db.execute(
            'INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
            ('search', caller['username'], f"{search_field}:{search_value}")
        )
        db.commit()
        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    api_key = request.headers.get('X-API-Key')
    caller = verify_api_key(api_key)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    row = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(row))

@app.route('/api/users/<int:user_id>/role', methods=['PUT'])
def update_role(user_id):
    api_key = request.headers.get('X-API-Key')
    caller = verify_api_key(api_key)
    if not caller or caller['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    new_role = request.json.get('role', '')
    if new_role not in ['user', 'admin', 'auditor']:
        return jsonify({'error': 'invalid role'}), 400

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, user_id))
    db.execute(
        'INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
        ('role_change', caller['username'], f"user:{user_id}->role:{new_role}")
    )
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
